from pathlib import Path
p=Path(__file__).with_name('main.js')
s=p.read_text()
def replace_function(name,code):
 global s
 start=s.index('function '+name+'(')
 end=s.find('\nfunction ',start+1)
 # Function blocks here are intentionally compact one-line definitions.
 line_end=s.find('\n',start)
 if name in ['simulate']:
  raise RuntimeError('do not replace whole simulation')
 s=s[:start]+code+s[line_end:]
old=next(line for line in s.splitlines() if line.startswith('const network=createNetwork('))
s=s.replace(old,"""let friendBody=null,menuAxisTimer=0,sliderAxisTimer=0,lastRemoteMode=null;
const remoteActions=[];
const neutralControls=()=>({x:0,z:0,sneak:false,lift:false});
const network=createNetwork({
 onStatus:s=>{$('network-status').textContent=s},
 onInput:(seat,value)=>{if(!value||typeof value!=='object')return;remoteInputs.set(seat,{x:clamp(Number(value.x)||0,-1,1),z:clamp(Number(value.z)||0,-1,1),sneak:!!value.sneak,lift:!!value.lift,at:performance.now()});if(value.interact||value.pulse||Number.isInteger(value.note))remoteActions.push({seat,action:{interact:!!value.interact,pulse:!!value.pulse,note:value.note}})},
 onAction:(seat,action)=>remoteActions.push({seat,action}),
 onState:state=>applySnapshot(state),onStart:()=>startGame(),onTimeUp:()=>finishHub(),
 onEnd:()=>{mode='ended';remoteInputs.clear();remoteActions.length=0;showScreen(null);$('hud').classList.add('hidden');audio.setMusic(0);audio.setSfx(0)},
 onPeerJoin:()=>{syncFriend();toast('A friend has found your little world.')},
 onPeerLeave:seat=>{remoteInputs.delete(seat);for(let i=remoteActions.length-1;i>=0;i--)if(remoteActions[i].seat===seat)remoteActions.splice(i,1);syncFriend();if(!authority()){mode='waiting';showScreen(null);$('hud').classList.add('hidden');toast('Your friend disconnected. Open the menu to return home.')}},
 onConnect:()=>{syncFriend();if(ready&&network.hubActive&&mode==='title')$('title').classList.add('hidden')}
});""")
replace_function('currentSeat',"function currentSeat(){return network.me??0}")
replace_function('authority',"""function authority(){return network.isHost}
function seatSlot(seat){const index=network.players.findIndex(p=>p.id===seat);return index<0?-1:index}
function currentSlot(){return Math.max(0,seatSlot(currentSeat()))}
function localPosition(){const hero=players[currentSlot()];return currentSlot()===0&&body?body.translation():hero?{x:hero.position.x,y:hero.position.y+.9,z:hero.position.z}:{x:0,y:1.25,z:18}}
function seatControls(slot,local){const seat=network.players[slot]?.id;if(seat===currentSeat()&&!network.isServer)return local||neutralControls();const value=remoteInputs.get(seat);return value&&performance.now()-value.at<700?value:neutralControls()}
function syncFriend(){if(!ready||!players[1]||!physics)return;const enabled=network.players.length>1;if(!friendBody){friendBody=physics.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(-2,1.25,19).lockRotations().setLinearDamping(6).setCcdEnabled(true));physics.createCollider(RAPIER.ColliderDesc.capsule(.4,.46).setFriction(0).setRestitution(0),friendBody)}const fresh=enabled&&!players[1].visible;players[1].visible=enabled;friendBody.setEnabled(enabled&&authority());if(fresh&&authority()){const p=body.translation();friendBody.setTranslation({x:p.x-2,y:p.y,z:p.z+1},true);friendBody.setLinvel({x:0,y:0,z:0},true);players[1].position.set(p.x-2,p.y-.9,p.z+1)}}
function processRemoteActions(){if(!authority())return;while(remoteActions.length){const {seat,action}=remoteActions.shift(),slot=seatSlot(seat);if(slot<0||!action||typeof action!=='object')continue;const position=slot===0?body.translation():{x:players[slot].position.x,y:players[slot].position.y+.9,z:players[slot].position.z};if(action.pause&&(mode==='play'||mode==='signal'))pause(true);if(action.resume&&['pause','settings','about','coop','dev'].includes(mode))resume(true);if(action.cancelSignal&&mode==='signal'){mode='play';showScreen(null)}if(Number.isInteger(action.note)&&action.note>=0&&action.note<3)submitNote(action.note,true);if(action.interact)interact(position);if(action.pulse)pulse(position)}}
function closeSignal(){if(!authority()){network.sendAction({cancelSignal:true});return}mode='play';showScreen(null)}
function prepareFriend(dt,controls){if(!friendBody?.isEnabled())return;const p=friendBody.translation();friendBody.setGravityScale(phase==='flight'?0:1,true);if(phase==='flight'){friendBody.setLinvel({x:controls.x*7.8,y:clamp(((controls.lift?8.5:2.2)-p.y)*1.8,-3,4),z:-balance.flightSpeed*(controls.sneak?1.35:1)},true)}else{friendBody.setLinvel({x:controls.x*(controls.sneak?balance.sneakSpeed:balance.rideSpeed),y:friendBody.linvel().y,z:controls.z*(controls.sneak?balance.sneakSpeed:balance.rideSpeed)},true)}}
function updateFriend(dt,controls){if(!friendBody?.isEnabled())return;const friend=players[1],p=friendBody.translation();if(phase==='flight'){friendBody.setTranslation({x:clamp(p.x,-16,16),y:p.y,z:p.z},true);friend.rotation.y=Math.PI+controls.x*.22;friend.rotation.z=-controls.x*.2;for(const h of world.hoops)if(!h.collected&&Math.abs(p.z-h.z)<2.5&&Math.hypot(p.x-h.x,p.y-h.y)<3.2){h.collected=true;h.mesh.visible=false;stars++;audio.sfx('pickup');particleBurst(h.x,h.y,h.z)}}else{friendBody.setTranslation({x:clamp(p.x,-34,34),y:p.y,z:clamp(p.z,-42,34)},true);if(Math.hypot(controls.x,controls.z)>.1)friend.rotation.y=Math.atan2(controls.x,controls.z);friend.rotation.z=0;for(const a of world.agents){const dx=p.x-a.x,dz=p.z-a.z,d=Math.hypot(dx,dz);if(a.stunned<=0&&d<(controls.sneak?3:7.8)&&(dx*Math.sin(a.mesh.rotation.y)+dz*Math.cos(a.mesh.rotation.y))/Math.max(.1,d)>.65){bond-=dt*balance.alertRate*(controls.sneak?.2:1);alert=clamp(alert+dt*40,0,100)}}for(const candy of world.candies)if(!candy.collected&&Math.hypot(candy.x-p.x,candy.z-p.z)<1.5){candy.collected=true;candy.mesh.visible=false;bond=clamp(bond+10,0,100);audio.sfx('pickup')}}const np=friendBody.translation();friend.position.set(np.x,np.y-.9,np.z);friend.userData.mixer.timeScale=phase==='flight'?1.5:Math.hypot(controls.x,controls.z)>.1?1:.15;friend.userData.mixer.update(dt)}""")
