# New readInput keeps actions separate from throttled movement and supports both menu stick and d-pad.
replace_function('readInput',"""function readInput(dt){if(mode==='ended'||network.isServer)return neutralControls();let x=0,z=0,sneak=false,lift=false;if(keys.has('KeyA')||keys.has('ArrowLeft'))x--;if(keys.has('KeyD')||keys.has('ArrowRight'))x++;if(keys.has('KeyW')||keys.has('ArrowUp'))z--;if(keys.has('KeyS')||keys.has('ArrowDown'))z++;sneak=keys.has('ShiftLeft')||keys.has('ShiftRight');lift=keys.has('Space');if(leftTouch){x=touchVector.x;z=touchVector.z}const p=Array.from(navigator.getGamepads?.()||[]).find(Boolean);menuAxisTimer=Math.max(0,menuAxisTimer-dt);sliderAxisTimer=Math.max(0,sliderAxisTimer-dt);if(p){const axes=p.axes,active=axes.some(v=>Math.abs(v)>.16)||p.buttons.some(b=>b.pressed);if(active&&rememberInput('pad'))return neutralControls();const btn=n=>p.buttons[n]?.pressed,edge=n=>btn(n)&&!padPrevious[n];if(mode==='play'){if(Math.hypot(axes[0]||0,axes[1]||0)>.15){x=axes[0];z=axes[1];clickTarget=null}cameraAngle-=(Math.abs(axes[2]||0)>.15?axes[2]:0)*dt*1.6*cameraSensitivity;sneak=btn(6);lift=btn(2);if(edge(0))interact();if(edge(2))pulse();if(edge(9)&&!btn(8))pause()}else if(mode==='signal'){if(edge(2))submitNote(0);if(edge(0))submitNote(1);if(edge(1))submitNote(2);if(edge(9)&&!btn(8))pause()}else{const axisY=axes[1]||0,axisX=axes[0]||0;if(Math.abs(axisY)<.3)menuAxisTimer=0;if(Math.abs(axisX)<.3)sliderAxisTimer=0;if(edge(13)||edge(12)){menuMove(edge(13)?1:-1);menuAxisTimer=.25}else if(Math.abs(axisY)>.6&&menuAxisTimer===0){menuMove(axisY>0?1:-1);menuAxisTimer=.25}if(edge(0))document.activeElement?.click();if(edge(1)||(edge(9)&&!btn(8))){if(mode==='pause')resume();else if(mode==='waiting'&&!network.hubActive)toTitle();else if(mode!=='title'&&mode!=='waiting')back()}const activeEl=document.activeElement;if(activeEl?.type==='range'&&(edge(14)||edge(15)||(Math.abs(axisX)>.6&&sliderAxisTimer===0))){const direction=edge(15)?1:edge(14)?-1:Math.sign(axisX);activeEl.value=clamp(+activeEl.value+direction*Number(activeEl.step||1),+activeEl.min,+activeEl.max);activeEl.dispatchEvent(new Event('input'));sliderAxisTimer=.25}}padPrevious=p.buttons.map(b=>b.pressed)}if(x||z){clickTarget=null;const length=Math.hypot(x,z);if(length>1){x/=length;z/=length}}else if(clickTarget&&mode==='play'){const pos=localPosition(),dx=clickTarget.x-pos.x,dz=clickTarget.z-pos.z,length=Math.hypot(dx,dz);if(length<.6)clickTarget=null;else return{x:dx/length,z:dz/length,sneak,lift}}const c=Math.cos(cameraAngle),s=Math.sin(cameraAngle);return{x:x*c-z*s,z:x*s+z*c,sneak,lift:lift||input.lift};}""")
