replace_function('nearestInteraction',"function nearestInteraction(position=localPosition()){if(!body||phase==='flight')return null;const p=position;const near=(t,d=3)=>Math.hypot(t.x-p.x,t.z-p.z)<d;if(phase==='scavenge'){const target=world.targets.find(t=>!inventory.includes(t.id)&&near(t));if(target)return{kind:'part',target,text:'Borrow '+target.name}}const flower=world.flowers.find(f=>!f.healed&&near(f,2.8));if(flower)return{kind:'flower',target:flower,text:'Make a little life glow'};if(inventory.length===3&&near({x:0,z:-35},4.5))return{kind:'signal',text:'Call the stars'};return null}")
