replace_function('snapshot',"function snapshot(){return{mode:['pause','settings','about','coop','dev'].includes(mode)?'pause':mode,pausedFrom,phase,bond,inventory,flowersHealed,stars,pulses,elapsed,alert,flightDistance,clockTime,signalIndex,signalTimer,signalShow,signalReady,players:players.map(p=>({x:p.position.x,y:p.position.y,z:p.position.z,r:p.rotation.y,roll:p.rotation.z,visible:p.visible})),alien:{x:alien.position.x,y:alien.position.y,z:alien.position.z,r:alien.rotation.y,scale:alien.scale.x},agents:world.agents.map(a=>({x:a.x,z:a.z,r:a.mesh.rotation.y,stunned:a.stunned})),flowers:world.flowers.map(f=>f.healed),candies:world.candies.map(c=>c.collected),hoops:world.hoops.map(h=>h.collected)}}")
replace_function('applySnapshot',"""function applySnapshot(s){if(!ready||authority()||!s||network.info.ended)return;const previousPhase=phase,previousInventory=inventory.length,previousPulses=pulses,previousShow=signalShow;phase=s.phase;bond=s.bond;inventory=s.inventory||[];flowersHealed=s.flowersHealed;stars=s.stars;pulses=s.pulses;elapsed=s.elapsed;alert=s.alert;flightDistance=s.flightDistance;clockTime=s.clockTime??clockTime;pausedFrom=s.pausedFrom||'play';if(s.mode==='win'){if(mode!=='win')winGame()}else if(s.mode==='signal'){if(mode!=='signal'){mode='signal';showScreen('signal');$('signal-seq').innerHTML=pattern.map(()=>'<span class="signal-dot">·</span>').join('')}signalIndex=s.signalIndex??0;signalTimer=s.signalTimer??0;signalShow=s.signalShow??-1;signalReady=!!s.signalReady;[...$('signal-seq').children].forEach((e,i)=>{e.classList.toggle('lit',signalReady?i<signalIndex:i===signalShow);e.textContent=signalReady||i===signalShow?['◒','✦','☾'][pattern[i]]:'·'});$('signal-instruction').textContent=signalReady?'Your turn. Send the lights back, one by one.':'Listen to the little lights. Then send their song back.';document.querySelectorAll('[data-note]').forEach(b=>b.disabled=!signalReady);if(!signalReady&&signalShow>=0&&signalShow!==previousShow)signalSound(pattern[signalShow]);$('hud').classList.remove('hidden')}else if(s.mode==='pause'){if(!['pause','settings','about','coop','dev'].includes(mode)){mode='pause';showScreen('pause')}$('hud').classList.add('hidden')}else if(s.mode==='play'){if(mode!=='play'){mode='play';showScreen(null);$('hud').classList.remove('hidden')}}else if(s.mode==='title'||s.mode==='waiting'){if(mode!=='waiting'){mode='waiting';showScreen(null);$('hud').classList.add('hidden');toast('Your friend is choosing the next adventure.')}}s.players?.forEach((p,i)=>{if(players[i]){players[i].position.set(p.x,p.y,p.z);players[i].rotation.set(0,p.r,p.roll||0);players[i].visible=p.visible;if(i===0)body.setTranslation({x:p.x,y:p.y+.9,z:p.z},true)}});if(s.alien){alien.position.set(s.alien.x,s.alien.y,s.alien.z);alien.rotation.y=s.alien.r||0;alien.scale.setScalar(s.alien.scale||1)}s.agents?.forEach((a,i)=>{const target=world.agents[i];if(target){target.x=a.x;target.z=a.z;target.stunned=a.stunned;target.mesh.position.set(a.x,0,a.z);target.mesh.rotation.y=a.r}});world.targets.forEach(t=>t.mesh.visible=!inventory.includes(t.id));s.flowers?.forEach((v,i)=>{if(world.flowers[i])world.flowers[i].healed=v});s.candies?.forEach((v,i)=>{if(world.candies[i]){world.candies[i].collected=v;world.candies[i].mesh.visible=!v}});s.hoops?.forEach((v,i)=>{if(world.hoops[i]){world.hoops[i].collected=v;world.hoops[i].mesh.visible=!v}});if(inventory.length>previousInventory)audio.sfx('pickup');if(pulses>previousPulses){const p=localPosition();spawnRing(p.x,.2,p.z,0x9eeacc,8);audio.sfx('pulse')}if(phase!==previousPhase){updatePrompts();audio.setMood(phase==='flight'?'flight':'explore');if(phase==='flight')cameraAngle=0}lastRemoteMode=s.mode;updateHUD()}""")
