replace_function('frame',"""function frame(now){if(!ready)return;const dt=Math.min((now-lastFrame)/1000||.016,.06);lastFrame=now;const controls=readInput(dt)||neutralControls();input.sneak=controls.sneak;if(network.active&&network.running&&!network.isServer)network.sendInput(mode==='play'?controls:neutralControls());if(authority()&&network.running)processRemoteActions();if(mode==='title'&&!network.hubActive&&authority()){titleIdle+=dt;world.update(clockTime+=dt,dt);alien.userData.mixer.update(dt*.2);if(titleIdle>=10)startGame({demo:true})}if(mode==='play'&&network.running){if(authority()){const c=attract?autoInput(dt):seatControls(0,controls);accumulator+=dt;let count=0;while(accumulator>=1/60&&count++<4){simulate(1/60,c);accumulator-=1/60}}else{world.update(clockTime,dt);players.forEach(p=>p.userData.mixer.update(dt));alien.userData.mixer.update(dt);updateEffects(dt);updateTrail()}}else if(mode==='signal'&&authority()&&network.running){updateSignal(dt);if(attract&&signalReady){attractTimer+=dt;if(attractTimer>.5){submitNote(pattern[signalIndex]);attractTimer=0}}}else if(mode==='win'){winTimer+=dt;world.update(clockTime+=dt,dt);if(attract&&winTimer>5)startGame({demo:true})}if(authority()&&network.active&&network.running)network.broadcast(snapshot());if(dialogueTimer>0){dialogueTimer-=dt;if(dialogueTimer<=0)$('dialogue').classList.add('hidden')}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.add('hidden')}if(mode!=='ended')audio.update(dt);if(!network.isServer)updateCamera(dt);if(mode==='play')updateHUD();renderer.render(scene,camera);requestAnimationFrame(frame)}let lastFrame=performance.now();""")
